<script setup>
import AppSkeleton from "../common/AppSkeleton.vue"
import {ref,reactive,watch,inject,nextTick,computed} from 'vue'
import {addressesApi} from '../../api/addresses.api'
import {useAuthStore} from '../../stores/auth'
import {useBranchStore} from '../../stores/branch'
import {useApiState,useApiMutation} from '../../composables/useApiState'
import {addressForm,addressPayload} from '../../constants/addressFields'
import AddressFields from './AddressFields.vue'
import SiteIcon from './SiteIcon.vue'
const props=defineProps({selectable:Boolean,selectedId:String,management:Boolean})
const emit=defineEmits(['selected','changed'])
const auth=useAuthStore(),state=useApiState(),mutation=useApiMutation(),recordLoading=ref(false),editing=ref(null),showForm=ref(false),form=reactive(addressForm()),deleting=ref(null),confirmation=ref(null)
const {toast}=inject('site')
const branches=useBranchStore()
const editor=ref(null)
function mapsUrl(item){const lat=item.location?.latitude,lng=item.location?.longitude;if(lat===null||lat===undefined||lng===null||lng===undefined||String(lat).trim()===''||String(lng).trim()==='')return null;const latitude=Number(lat),longitude=Number(lng);return Number.isFinite(latitude)&&Number.isFinite(longitude)&&Math.abs(latitude)<=90&&Math.abs(longitude)<=180?'https://www.google.com/maps/search/?api=1&query='+encodeURIComponent(latitude+','+longitude):null}
let revision=0
function load(){if(auth.isAuthenticated)return state.run(signal=>addressesApi.list(signal))}
defineExpose({reload:load})
const addressLimit=3
const limitReached=computed(()=>(state.data.value?.length||0)>=addressLimit)
watch(()=>auth.token,()=>{revision++;state.clear();mutation.error.value=null;showForm.value=false;Object.assign(form,addressForm());emit('selected',null);load()},{immediate:true})
async function edit(record){
  if(!record&&limitReached.value)return
  mutation.error.value=null
  const version=revision
  if(record){recordLoading.value=true;let result;try{result=await mutation.run(()=>addressesApi.show(record.id))}finally{recordLoading.value=false};if(!result.ok){if(mutation.error.value?.status===404)load();return}if(version!==revision)return;record=result.data}
  editing.value=record
  Object.assign(form,addressForm(record||{recipient_name:auth.user?.name||'',phone:auth.user?.phone||'',city:branches.selectedBranch?.name?.includes('المصيف')?'تبوك':branches.selectedBranch?.location?.city||''}))
  showForm.value=true
  if(props.management){await nextTick();editor.value?.scrollIntoView({behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'});editor.value?.querySelector('input')?.focus({preventScroll:true})}
}
async function save(){
  if(!editing.value&&limitReached.value){toast('يمكنك حفظ ثلاثة عناوين فقط. احذف عنوانًا لإضافة عنوان جديد.');return}
  const version=revision
  const result=await mutation.run(()=>editing.value?addressesApi.update(editing.value.id,addressPayload(form)):addressesApi.create(addressPayload(form)))
  if(version!==revision)return
  if(result.ok){showForm.value=false;toast('تم حفظ العنوان.');emit('changed');if(props.selectedId===result.data.id||props.selectable)emit('selected',result.data);await load()}
  else if(mutation.error.value?.status===404){emit('selected',null);load()}
}
async function setDefault(record){const version=revision;const result=await mutation.run(()=>addressesApi.setDefault(record.id));if(version!==revision)return;if(result.ok){toast('تم تحديث العنوان الافتراضي.');emit('changed');load()}else if(mutation.error.value?.status===404)load()}
async function remove(){const record=deleting.value,version=revision;const result=await mutation.run(()=>addressesApi.remove(record.id));confirmation.value.close();if(version!==revision)return;if(result.ok){toast('تم حذف العنوان.');if(props.selectedId===record.id)emit('selected',null);emit('changed');load()}else if(mutation.error.value?.status===404){emit('selected',null);load()}}
</script>
<template>
 <section class="address-book" :class="{'address-book--management':management}" aria-labelledby="address-book-title">
  <div class="dialog-heading address-book-heading"><div><h2 id="address-book-title">{{ selectable?'اختر عنوان التوصيل':management?'عناوينك المحفوظة':'عناويني' }}</h2><p v-if="management">اختر عنوانك الافتراضي لتسهيل طلبك القادم.</p></div><button v-if="!limitReached" type="button" class="button button-primary" :disabled="state.loading.value||!state.data.value||mutation.busy.value||!auth.isAuthenticated||recordLoading||(management&&showForm)" @click="edit(null)">{{ management?'إضافة عنوان جديد':'إضافة عنوان' }}</button></div>
  <p v-if="limitReached" class="catalog-note">يمكنك حفظ ثلاثة عناوين فقط. عدّل عنوانًا أو احذفه لإضافة عنوان جديد.</p>
  <AppSkeleton v-if="state.loading.value" variant="list" label="جارٍ تحميل العناوين…"/>
  <div v-if="state.error.value" class="address-message" role="alert"><p>{{ state.error.value.message }}</p><button type="button" class="text-button" @click="load">إعادة المحاولة</button></div>
  <div v-if="state.data.value&&!state.data.value.length" class="address-empty"><SiteIcon v-if="management" name="map-pin"/><h3 v-if="management">أين نوصّل طلبك؟</h3><p class="catalog-note">{{ management?'أضف عنوانك مرة واحدة، واختره بسهولة مع كل طلب جديد.':'ليس لديك عناوين محفوظة. يمكنك إضافة عنوان أو إدخاله يدويًا للتوصيل.' }}</p></div>
  <div class="address-list"><article v-for="item in state.data.value||[]" :key="item.id" class="checkout-panel address-card" :class="{'address-card--default':item.is_default}">
   <div class="address-card-heading"><span v-if="management" class="address-pin"><SiteIcon name="map-pin"/></span><div><h3>{{ item.label||item.recipient_name }}</h3><span v-if="item.is_default" class="badge good address-default-badge"><SiteIcon v-if="management" name="badge-check"/> العنوان الافتراضي</span></div></div>
   <div class="address-card-body"><p class="address-contact">{{ item.recipient_name }} · <bdi>{{ item.phone }}</bdi></p><p class="address-street">{{ [item.city,item.district,item.street].filter(Boolean).join('، ') }}<span v-if="item.building_number"> · مبنى {{ item.building_number }}</span></p><p v-if="item.floor||item.apartment" class="address-extra">{{ [item.floor?'الطابق '+item.floor:null,item.apartment?'الشقة '+item.apartment:null].filter(Boolean).join(' · ') }}</p><p v-if="item.landmark" class="address-extra">{{ item.landmark }}</p><p v-if="item.notes" class="address-notes">{{ item.notes }}</p></div>
   <a v-if="management&&mapsUrl(item)" :href="mapsUrl(item)" target="_blank" rel="noopener noreferrer" class="address-map-link"><SiteIcon name="map-pin"/> فتح على الخريطة <SiteIcon name="arrow-up-left"/></a>
   <div class="form-actions address-card-actions"><button type="button" v-if="selectable" class="button" :aria-pressed="selectedId===item.id" :disabled="mutation.busy.value" @click="emit('selected',item)">{{ selectedId===item.id?'العنوان المختار':'اختيار للتوصيل' }}</button><button type="button" class="text-button" :disabled="mutation.busy.value||recordLoading" @click="edit(item)">تعديل</button><button type="button" v-if="!item.is_default" class="text-button" :disabled="mutation.busy.value||recordLoading" @click="setDefault(item)">تعيين افتراضي</button><button type="button" class="text-button address-delete" :disabled="mutation.busy.value||recordLoading" @click="deleting=item;confirmation.showModal()">حذف</button></div>
  </article></div>
  <AppSkeleton v-if="recordLoading" variant="inline" label="جارٍ تحميل تفاصيل العنوان…"/>
  <form v-if="showForm" ref="editor" class="checkout-panel address-editor" @submit.prevent="save"><div class="address-editor-heading"><span v-if="management" class="address-pin"><SiteIcon name="map-pin"/></span><div><h3>{{ editing?'تعديل العنوان':'عنوان جديد' }}</h3><p v-if="management">حدّد الموقع على الخريطة، ثم أكمل بيانات المستلم.</p></div></div><AddressFields :key="editing?.id || 'new'" :center="branches.selectedBranch?.location" :form="form" :errors="mutation.error.value?.errors" :disabled="mutation.busy.value"/><div class="form-actions address-editor-actions"><button type="submit" class="button button-primary" :disabled="mutation.busy.value">{{ mutation.busy.value?'جارٍ الحفظ…':'حفظ العنوان' }}</button><button type="button" class="button" :disabled="mutation.busy.value" @click="showForm=false;Object.assign(form,addressForm())">إلغاء</button></div></form>
  <div v-if="mutation.error.value" class="address-message" role="alert"><p>{{ mutation.error.value.message }}</p><p v-for="(messages,key) in mutation.error.value.errors" :key="key">{{ messages.join(' ') }}</p></div>
  <dialog ref="confirmation" class="info-dialog address-delete-dialog" aria-labelledby="delete-address-title"><h2 id="delete-address-title">حذف العنوان؟</h2><p>سيُحذف هذا العنوان من عناوينك المحفوظة. يمكنك إضافته مرة أخرى لاحقًا.</p><p v-if="deleting?.is_default">سيُختار عنوان آخر كعنوان افتراضي إن وجد.</p><div class="form-actions"><button type="button" class="button button-primary" :disabled="mutation.busy.value" @click="remove">حذف</button><button type="button" class="button" :disabled="mutation.busy.value" @click="confirmation.close()">إلغاء</button></div></dialog>
 </section>
</template>
<style scoped>
.address-book--management .address-book-heading{display:flex;align-items:center;justify-content:space-between;gap:16px;flex-wrap:wrap;margin-bottom:22px}.address-book--management .address-book-heading h2{font-size:19px}.address-book--management .address-book-heading p{color:var(--muted);font-size:13px;margin-top:5px}.address-book--management .address-book-heading .button{min-height:44px;border-radius:10px}
.address-book--management .address-list{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px}.address-book--management .address-card{margin:0;min-width:0;padding:22px;border:1px solid var(--border);border-radius:16px;background:#fff;display:flex;flex-direction:column}.address-book--management .address-card--default{border-color:#c9963b88;background:#fffcf7}.address-book--management .address-card-heading,.address-book--management .address-editor-heading{display:flex;align-items:flex-start;gap:12px;margin-bottom:18px}.address-book--management .address-pin{display:grid;place-items:center;width:44px;height:44px;flex-shrink:0;border-radius:12px;background:#5a172508;color:var(--primary)}.address-book--management .address-card--default .address-pin{background:#c9963b15}.address-book--management .address-card-heading>div{min-width:0}.address-book--management .address-card h3{font-size:18px;line-height:1.6;overflow-wrap:anywhere}.address-book--management .address-default-badge{display:inline-flex;align-items:center;gap:5px;color:#865d1a;background:#c9963b14;border:1px solid #c9963b30;font-size:10px;padding:4px 8px;margin-top:6px;border-radius:7px}.address-book--management .address-default-badge .icon{width:14px;height:14px}
.address-book--management .address-card-body{flex:1;overflow-wrap:anywhere}.address-book--management .address-contact{font-size:13px;font-weight:700;margin-bottom:10px}.address-book--management .address-street{font-size:14px;line-height:1.9}.address-book--management .address-extra{font-size:12px;color:var(--muted);margin-top:5px}.address-book--management .address-notes{font-size:12px;color:var(--muted);padding:10px 12px;border-radius:8px;background:#5a172505;margin-top:12px;white-space:pre-line}.address-book--management .address-map-link{display:inline-flex;align-items:center;align-self:flex-start;gap:7px;min-height:44px;font-size:12px;font-weight:700;color:var(--primary);margin-top:12px}.address-book--management .address-map-link .icon{width:17px;height:17px}
.address-book--management .address-card-actions{border-top:1px solid var(--border);padding-top:14px;margin:14px 0 0;display:flex;flex-wrap:wrap;gap:8px}.address-book--management .address-card-actions .text-button{min-height:40px;border:1px solid var(--border);border-radius:8px;padding:7px 14px;font-size:12px;background:#fff;color:var(--primary);text-decoration:none}.address-book--management .address-card-actions .address-delete{margin-inline-start:auto;color:#b42632;border-color:#eed9dc;background:#fff8f8}
.address-book--management .address-empty{padding:44px 24px;border:1px dashed var(--border);border-radius:16px;background:#fff;text-align:center}.address-book--management .address-empty>.icon{width:42px;height:42px;color:var(--gold);margin-bottom:12px}.address-book--management .address-empty h3{font-size:19px}.address-book--management .address-empty p{font-size:13px;color:var(--muted);margin:8px 0 0}.address-book--management .address-message{border:1px solid #efd2d2;border-radius:12px;background:#fff0f0;padding:16px;margin-block:16px;font-size:13px;color:var(--primary)}
.address-book--management .address-editor{margin:24px 0 0;padding:26px;border:1px solid var(--border);border-radius:16px;background:#fff;scroll-margin-top:115px}.address-book--management .address-editor-heading h3{font-size:20px}.address-book--management .address-editor-heading p{font-size:13px;color:var(--muted);margin-top:4px}.address-book--management .address-editor :deep(.address-editor-fields>.address-fields){margin-block:20px}.address-book--management .address-editor :deep(.field>span){font-size:13px;font-weight:700}.address-book--management .address-editor :deep(.field input),.address-book--management .address-editor :deep(.field textarea){background:var(--cream);border-radius:10px;font-size:14px}.address-book--management .address-editor :deep(.check){display:flex;align-items:center;gap:9px;margin-top:18px;font-size:13px}.address-book--management .address-editor-actions{border-top:1px solid var(--border);padding-top:18px;margin-top:22px}.address-book--management .address-editor-actions .button{min-height:44px}.address-book--management .address-delete-dialog{width:min(440px,calc(100% - 32px));padding:24px;border-radius:16px}.address-book--management .address-delete-dialog p{font-size:13px;color:var(--muted);margin-block:14px}
@media(max-width:700px){.address-book--management .address-list{grid-template-columns:minmax(0,1fr)}.address-book--management .address-card{padding:20px}.address-book--management .address-book-heading{align-items:flex-start}.address-book--management .address-book-heading .button{width:100%}.address-book--management .address-editor{padding:20px}.address-book--management .address-editor-actions .button{flex:1}.address-book--management .address-card-actions .text-button{padding-inline:12px}.address-book--management .address-card-actions .address-delete{margin-inline-start:auto}}
</style>

